// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserLearnTargetRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.UserLearnTarget) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserLearnTargetByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserLearnTargetByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserLearnTargetBySchoolIDPrefix, item.SchoolID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserLearnTargetByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserLearnTargetByUserIDPrefix, item.UserID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserLearnTargetByUserIDStatusPrefix, item.UserID, item.Status)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
